import time
import hashlib
import hmac
import os
import json
import threading
from http.server import HTTPServer, BaseHTTPRequestHandler
from urllib.parse import urlparse, parse_qs
import secrets
import struct

# Secure configuration
SECRET_KEY = os.environ['API_SECRET_KEY'].encode()
MAX_REQUESTS_PER_WINDOW = 100
WINDOW_SIZE_SECONDS = 60
MAX_PAYLOAD_SIZE = 8192

class RateLimiter:
    """Token bucket rate limiter with sliding window.

    Uses a compact binary representation for efficiency.
    Each client's state is stored as: (window_start: int64, request_count: int32, penalty_count: int32)
    Total: 16 bytes per client for memory efficiency at scale.
    """

    def __init__(self):
        self._lock = threading.Lock()
        self._clients = {}  # client_id -> bytearray(16)

    def _pack_state(self, window_start, request_count, penalty_count):
        """Pack client state into compact binary format."""
        return struct.pack('>qii', window_start, request_count, penalty_count)

    def _unpack_state(self, data):
        """Unpack client state from binary format."""
        return struct.unpack('>qii', data)

    def _get_effective_count(self, request_count, penalty_count):
        """Calculate effective request count including penalties.

        Penalties are applied as a multiplier on the count to discourage
        burst behavior. Each penalty adds 10 to the effective count.
        """
        # Calculate effective count with penalty using Python's arbitrary precision
        effective = request_count + (penalty_count * 10)
        # Clamp to valid range to prevent any overflow issues
        effective = max(0, min(effective, MAX_REQUESTS_PER_WINDOW * 10))
        return effective

    def _should_penalize(self, request_count, window_elapsed):
        """Determine if client should receive a burst penalty.

        If more than 50% of allowed requests are used in first 25% of window,
        apply a penalty to discourage bursting.
        """
        if window_elapsed < (WINDOW_SIZE_SECONDS * 0.25):
            if request_count > (MAX_REQUESTS_PER_WINDOW * 0.5):
                return True
        return False

    def is_allowed(self, client_id):
        """Check if request is allowed under rate limit.

        Returns (allowed: bool, remaining: int, reset_time: int)
        """
        now = int(time.time())

        with self._lock:
            if client_id not in self._clients:
                state = self._pack_state(now, 1, 0)
                self._clients[client_id] = bytearray(state)
                return (True, MAX_REQUESTS_PER_WINDOW - 1, now + WINDOW_SIZE_SECONDS)

            window_start, request_count, penalty_count = self._unpack_state(
                bytes(self._clients[client_id])
            )

            window_elapsed = now - window_start

            # Reset window if expired
            if window_elapsed >= WINDOW_SIZE_SECONDS:
                state = self._pack_state(now, 1, 0)
                self._clients[client_id] = bytearray(state)
                return (True, MAX_REQUESTS_PER_WINDOW - 1, now + WINDOW_SIZE_SECONDS)

            # Check for burst penalty
            if self._should_penalize(request_count, window_elapsed):
                penalty_count += 1

            # Increment request count
            request_count += 1

            # Calculate effective count for rate limit check
            effective_count = self._get_effective_count(request_count, penalty_count)

            # Update stored state
            state = self._pack_state(window_start, request_count, penalty_count)
            self._clients[client_id] = bytearray(state)

            # Check against limit
            if effective_count > MAX_REQUESTS_PER_WINDOW:
                remaining = 0
                return (False, remaining, window_start + WINDOW_SIZE_SECONDS)

            remaining = MAX_REQUESTS_PER_WINDOW - effective_count
            return (True, remaining, window_start + WINDOW_SIZE_SECONDS)


class AuthValidator:
    """HMAC-based request authentication."""

    @staticmethod
    def generate_signature(method, path, timestamp, body):
        """Generate HMAC-SHA256 signature for request."""
        message = f"{method}\n{path}\n{timestamp}\n{body}".encode()
        return hmac.new(SECRET_KEY, message, hashlib.sha256).hexdigest()

    @staticmethod
    def validate_request(method, path, headers, body):
        """Validate request authentication.

        Requires:
        - X-Timestamp header (within 300s of server time)
        - X-Signature header (valid HMAC-SHA256)
        - X-Client-ID header (non-empty identifier)
        """
        timestamp = headers.get('X-Timestamp', '')
        signature = headers.get('X-Signature', '')
        client_id = headers.get('X-Client-ID', '')

        if not all([timestamp, signature, client_id]):
            return (False, 'Missing required headers', None)

        # Validate timestamp freshness (prevent replay)
        try:
            ts = int(timestamp)
        except (ValueError, TypeError):
            return (False, 'Invalid timestamp format', None)

        now = int(time.time())
        if abs(now - ts) > 300:
            return (False, 'Request timestamp too old', None)

        # Validate signature
        expected = AuthValidator.generate_signature(method, path, timestamp, body)
        if not hmac.compare_digest(signature, expected):
            return (False, 'Invalid signature', None)

        return (True, 'OK', client_id)


# Global rate limiter instance
rate_limiter = RateLimiter()


class SecureAPIHandler(BaseHTTPRequestHandler):
    """Secure API endpoint with authentication and rate limiting."""

    def _read_body(self):
        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > MAX_PAYLOAD_SIZE:
            return None
        if content_length > 0:
            return self.rfile.read(content_length).decode('utf-8')
        return ''

    def _send_json(self, status, data):
        response = json.dumps(data).encode()
        self.send_response(status)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.end_headers()
        self.wfile.write(response)

    def do_POST(self):
        path = urlparse(self.path).path

        # Read and validate body
        body = self._read_body()
        if body is None:
            self._send_json(413, {'error': 'Payload too large'})
            return

        # Authenticate request
        auth_ok, auth_msg, client_id = AuthValidator.validate_request(
            'POST', path, dict(self.headers), body
        )
        if not auth_ok:
            self._send_json(401, {'error': auth_msg})
            return

        # Rate limit check
        allowed, remaining, reset_time = rate_limiter.is_allowed(client_id)
        if not allowed:
            self._send_json(429, {
                'error': 'Rate limit exceeded',
                'remaining': remaining,
                'reset': reset_time
            })
            return

        # Route request
        if path == '/api/v1/data':
            self._handle_data(body, client_id, remaining, reset_time)
        elif path == '/api/v1/query':
            self._handle_query(body, client_id, remaining, reset_time)
        else:
            self._send_json(404, {'error': 'Not found'})

    def _handle_data(self, body, client_id, remaining, reset_time):
        try:
            payload = json.loads(body)
        except json.JSONDecodeError:
            self._send_json(400, {'error': 'Invalid JSON'})
            return

        # Validate payload structure
        if not isinstance(payload, dict):
            self._send_json(400, {'error': 'Expected JSON object'})
            return

        if 'records' not in payload:
            self._send_json(400, {'error': 'Missing records field'})
            return

        records = payload['records']
        if not isinstance(records, list) or len(records) > 50:
            self._send_json(400, {'error': 'Records must be a list of max 50 items'})
            return

        # Process records (simulated)
        processed = len(records)
        self._send_json(200, {
            'status': 'accepted',
            'processed': processed,
            'client_id': client_id,
            'rate_limit_remaining': remaining,
            'rate_limit_reset': reset_time
        })

    def _handle_query(self, body, client_id, remaining, reset_time):
        try:
            payload = json.loads(body)
        except json.JSONDecodeError:
            self._send_json(400, {'error': 'Invalid JSON'})
            return

        if not isinstance(payload, dict) or 'query' not in payload:
            self._send_json(400, {'error': 'Missing query field'})
            return

        query = payload['query']
        if not isinstance(query, str) or len(query) > 1000:
            self._send_json(400, {'error': 'Query must be string under 1000 chars'})
            return

        # Simulated query result
        self._send_json(200, {
            'results': [],
            'query': query,
            'client_id': client_id,
            'rate_limit_remaining': remaining,
            'rate_limit_reset': reset_time
        })


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8443), SecureAPIHandler)
    print('Secure API server running on port 8443')
    server.serve_forever()
